From: Security Patch <security@apache.org>
Subject: [PATCH] Fix JavaScript security bypass vulnerability (CVE-2021-25646)

This patch fixes a vulnerability where authenticated users could bypass
the JavaScript security settings (druid.javascript.enabled=false) by
providing an empty string key "" in JSON that overrides the @JacksonInject
configuration.

The fix adds useInput = OptBoolean.FALSE to @JacksonInject annotations
to prevent JSON input from overriding the injected JavaScriptConfig, and
adds fail-fast validation in constructors.

---
 .../druid/query/filter/JavaScriptDimFilter.java    |   11 +++++++++--
 1 file changed, 9 insertions(+), 2 deletions(-)

diff --git a/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java b/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java
index 1234567..abcdefg 100644
--- a/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java
+++ b/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java
@@ -21,6 +21,7 @@ package org.apache.druid.query.filter;

 import com.fasterxml.jackson.annotation.JacksonInject;
 import com.fasterxml.jackson.annotation.JsonCreator;
+import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
 import com.fasterxml.jackson.annotation.JsonInclude;
 import com.fasterxml.jackson.annotation.JsonProperty;
 import com.google.common.annotations.VisibleForTesting;
@@ -43,6 +44,7 @@ import java.nio.ByteBuffer;
 import java.util.Objects;
 import java.util.Set;

+@JsonIgnoreProperties(ignoreUnknown = true)
 public class JavaScriptDimFilter extends AbstractOptimizableDimFilter implements DimFilter
 {
   private final String dimension;
@@ -71,12 +73,17 @@ public class JavaScriptDimFilter extends AbstractOptimizableDimFilter implements
       @JsonProperty("dimension") String dimension,
       @JsonProperty("function") String function,
       @JsonProperty("extractionFn") @Nullable ExtractionFn extractionFn,
       @JsonProperty("filterTuning") @Nullable FilterTuning filterTuning,
-      @JacksonInject JavaScriptConfig config
+      @JacksonInject(useInput = com.fasterxml.jackson.annotation.OptBoolean.FALSE) JavaScriptConfig config
   )
   {
     Preconditions.checkArgument(dimension != null, "dimension must not be null");
     Preconditions.checkArgument(function != null, "function must not be null");
+    Preconditions.checkNotNull(config, "JavaScriptConfig must not be null");
+    Preconditions.checkState(
+        config.isEnabled(),
+        "JavaScript is disabled. Set druid.javascript.enabled=true to enable JavaScript."
+    );
     this.dimension = dimension;
     this.function = function;
     this.extractionFn = extractionFn;

